import crypto from 'node:crypto';
import fs from 'node:fs';

const BASE = 'http://127.0.0.1:9000';

async function getPublicKey() {
  const res = await fetch(`${BASE}/api/crypto/public_key`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ timestamp: Date.now(), fingerprint: crypto.randomUUID() }),
  });
  if (!res.ok) throw new Error(`public_key ${res.status}`);
  return (await res.json()).public_key;
}

function encrypt(publicKey, obj) {
  return crypto
    .publicEncrypt(
      { key: publicKey, padding: crypto.constants.RSA_PKCS1_PADDING },
      Buffer.from(JSON.stringify(obj), 'utf8'),
    )
    .toString('base64');
}

// 登录
const pk = await getPublicKey();
const loginRes = await fetch(`${BASE}/api/login`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    encrypted_params: encrypt(pk, { name: 'admin', password: 'NginxUi@2026' }),
  }),
});
const loginText = await loginRes.text();
console.log('login status =', loginRes.status);
if (!loginRes.ok) {
  console.log('login body   =', loginText);
  process.exit(1);
}
const token = JSON.parse(loginText).token ?? loginRes.headers.get('set-cookie');
