function MakeSymlink($name){
  $en="D:\nginx\conf\sites-enabled\$name.conf"
  $av="D:\nginx\conf\sites-available\$name"
  if(-not (Test-Path $av)){ Write-Output "NO AVAILABLE for $name"; return }
  $item=Get-Item $en -ErrorAction SilentlyContinue
  if($item -and $item.Attributes.ToString().Contains('ReparsePoint')){ Write-Output "already symlink: $name"; return }
  # 核对内容一致
  $same = ((Get-FileHash $en).Hash -eq (Get-FileHash $av).Hash)
  if(-not $same){ Write-Output "CONTENT DIFF skip: $name"; return }
  Remove-Item $en -Force
  New-Item -ItemType SymbolicLink -Path $en -Target $av | Out-Null
  Write-Output "symlink created: $name -> $av"
}
